// agent-guard plugin for OpenCode (generated by `guard install` from
// templates/opencode-plugin.js in the agent-guard repo; edit it there).
// After each shell command or file edit it asks agent-guard to check the change
// and appends any warning to the tool result, so the model sees it. Warn-only.
import { spawnSync } from "node:child_process";

const GUARD = "__GUARD_BIN__";
const AGENT = "__AGENT__";
const SHELL_TOOLS = new Set(["bash", "shell"]);
const EDIT_TOOLS = new Set(["edit", "write", "multiedit", "patch", "apply_patch"]);

function guard(payload) {
  try {
    const r = spawnSync(GUARD, ["hook", "--agent", AGENT, "--format", "generic"], {
      input: JSON.stringify(payload),
      encoding: "utf8",
      timeout: 15000,
    });
    return JSON.parse(r.stdout || "{}");
  } catch {
    return {};
  }
}

function fileOf(args) {
  return args?.filePath ?? args?.file_path ?? args?.path ?? null;
}

export const AgentGuard = async ({ directory }) => {
  const argsByCall = new Map();
  return {
    "tool.execute.before": async (input, output) => {
      argsByCall.set(input.callID, output?.args ?? {});
    },
    "tool.execute.after": async (input, output) => {
      const args = argsByCall.get(input.callID) ?? output?.metadata?.args ?? {};
      argsByCall.delete(input.callID);
      const tool = String(input.tool ?? "").toLowerCase();
      let payload = null;
      if (SHELL_TOOLS.has(tool)) {
        payload = { event: "post_command", command: args.command ?? "" };
      } else if (EDIT_TOOLS.has(tool)) {
        const f = fileOf(args);
        const text = args.content ?? args.newString ?? null;
        payload = { event: "post_edit", files: f ? [f] : [], edits: f && text ? { [f]: text } : {} };
      }
      if (!payload) return;
      const res = guard({ ...payload, cwd: directory, session_id: input.sessionID ?? "" });
      if (res.agent && output && typeof output.output === "string") {
        output.output += "\n\n" + res.agent;
      }
    },
  };
};
